-- migrate:up

create table order_counters (
  tenant_id uuid not null references tenants (id),
  business_date date not null,
  last_number integer not null check (last_number >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (tenant_id, business_date)
);

create table orders (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants (id),
  -- Idempotency key generated by the device (SPEC §7.2, §14.1).
  client_order_id uuid not null,
  order_number integer not null check (order_number >= 1),
  business_date date not null,
  -- Check-constrained text, not an enum, so new states can be added by migration (SPEC §14.2).
  status text not null check (status in ('paid', 'voided')),
  source text not null default 'pos' check (source in ('pos')),
  order_type text not null check (order_type in ('dine_in', 'takeaway')),
  customer_name text check (length(customer_name) <= 60),
  note text check (length(note) <= 500),
  subtotal bigint not null check (subtotal >= 0),
  item_discount_total bigint not null default 0 check (item_discount_total >= 0),
  order_discount_id uuid,
  order_discount_name text,
  order_discount_kind text check (order_discount_kind in ('percent', 'fixed')),
  order_discount_value bigint,
  order_discount_amount bigint not null default 0 check (order_discount_amount >= 0),
  net_sales bigint not null check (net_sales >= 0),
  service_charge_bps integer not null default 0 check (service_charge_bps between 0 and 10000),
  service_charge_amount bigint not null default 0 check (service_charge_amount >= 0),
  tax_name text,
  tax_bps integer not null default 0 check (tax_bps between 0 and 10000),
  tax_on_service_charge boolean not null default true,
  tax_amount bigint not null default 0 check (tax_amount >= 0),
  total bigint not null check (total >= 0),
  paid_total bigint not null,
  change_due bigint not null default 0 check (change_due >= 0),
  cogs_total bigint not null default 0 check (cogs_total >= 0),
  created_by_user_id uuid not null,
  device_id uuid,
  client_created_at timestamptz,
  paid_at timestamptz not null default now(),
  voided_at timestamptz,
  voided_by_user_id uuid,
  void_approved_by_user_id uuid,
  void_reason text check (length(void_reason) <= 500),
  void_restock boolean,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id),
  unique (tenant_id, client_order_id),
  unique (tenant_id, business_date, order_number),
  foreign key (tenant_id, order_discount_id) references discounts (tenant_id, id),
  foreign key (tenant_id, created_by_user_id) references users (tenant_id, id),
  foreign key (tenant_id, device_id) references devices (tenant_id, id),
  foreign key (tenant_id, voided_by_user_id) references users (tenant_id, id),
  foreign key (tenant_id, void_approved_by_user_id) references users (tenant_id, id),
  -- Money identities (SPEC §6.3). Defence in depth: the API computes these.
  constraint orders_net_sales check (net_sales = subtotal - item_discount_total - order_discount_amount),
  constraint orders_total check (total = net_sales + service_charge_amount + tax_amount),
  constraint orders_paid_total check (paid_total = total),
  constraint orders_void_fields check (
    (status = 'voided') = (voided_at is not null and voided_by_user_id is not null
                           and void_reason is not null and void_restock is not null)
  )
);
create index orders_business_date_idx on orders (tenant_id, business_date);

create table order_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants (id),
  order_id uuid not null,
  line_no integer not null check (line_no >= 1),
  item_id uuid not null,
  item_name text not null,
  category_name text not null,
  unit_price bigint not null check (unit_price >= 0),
  modifiers_unit_total bigint not null default 0 check (modifiers_unit_total >= 0),
  qty integer not null check (qty between 1 and 999),
  line_gross bigint not null,
  discount_id uuid,
  discount_name text,
  discount_kind text check (discount_kind in ('percent', 'fixed')),
  discount_value bigint,
  discount_amount bigint not null default 0,
  line_net bigint not null,
  note text check (length(note) <= 200),
  cogs numeric(16, 4) not null default 0 check (cogs >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id),
  unique (order_id, line_no),
  foreign key (tenant_id, order_id) references orders (tenant_id, id),
  foreign key (tenant_id, item_id) references items (tenant_id, id),
  foreign key (tenant_id, discount_id) references discounts (tenant_id, id),
  constraint order_lines_gross check (line_gross = (unit_price + modifiers_unit_total) * qty),
  constraint order_lines_discount check (discount_amount between 0 and line_gross),
  constraint order_lines_net check (line_net = line_gross - discount_amount)
);
create index order_lines_order_idx on order_lines (tenant_id, order_id);

create table order_line_modifiers (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants (id),
  order_line_id uuid not null,
  option_id uuid not null,
  group_name text not null,
  option_name text not null,
  price_delta bigint not null check (price_delta >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id),
  foreign key (tenant_id, order_line_id) references order_lines (tenant_id, id),
  foreign key (tenant_id, option_id) references modifier_options (tenant_id, id)
);
create index order_line_modifiers_line_idx on order_line_modifiers (tenant_id, order_line_id);

create table payments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants (id),
  order_id uuid not null,
  seq integer not null check (seq >= 1),
  method text not null check (method in ('cash', 'qris', 'debit', 'credit', 'transfer', 'other')),
  amount bigint not null check (amount > 0),
  tendered bigint,
  provider text check (length(provider) <= 40),
  reference text check (length(reference) <= 60),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id),
  unique (order_id, seq),
  foreign key (tenant_id, order_id) references orders (tenant_id, id),
  -- Cash lines record what was tendered (D-025); non-cash lines never do (SPEC §6.4).
  constraint payments_tendered check (
    (method = 'cash' and tendered is not null and tendered >= amount)
    or (method <> 'cash' and tendered is null)
  )
);
create index payments_order_idx on payments (tenant_id, order_id);

-- Append-only: zuru_app has INSERT + SELECT only (SPEC §4.1).
create table stock_movements (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants (id),
  ingredient_id uuid not null,
  type text not null check (type in ('sale', 'void_return', 'stock_in', 'waste', 'count_adjust')),
  qty_delta numeric(14, 3) not null,
  unit_cost numeric(16, 4) not null check (unit_cost >= 0),
  total_cost bigint check (total_cost >= 0),
  balance_after numeric(14, 3) not null,
  order_id uuid,
  reason text check (length(reason) <= 200),
  counted_qty numeric(14, 3) check (counted_qty >= 0),
  created_by_user_id uuid not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id),
  foreign key (tenant_id, ingredient_id) references ingredients (tenant_id, id),
  foreign key (tenant_id, order_id) references orders (tenant_id, id),
  foreign key (tenant_id, created_by_user_id) references users (tenant_id, id),
  constraint stock_movements_sign check (
    (type in ('sale', 'waste') and qty_delta < 0)
    or (type in ('void_return', 'stock_in') and qty_delta > 0)
    or (type = 'count_adjust' and qty_delta <> 0)
  ),
  constraint stock_movements_order check ((order_id is not null) = (type in ('sale', 'void_return'))),
  constraint stock_movements_total_cost check ((total_cost is not null) = (type = 'stock_in')),
  constraint stock_movements_counted check ((counted_qty is not null) = (type = 'count_adjust'))
);
create index stock_movements_ingredient_idx on stock_movements (tenant_id, ingredient_id, created_at);
create index stock_movements_order_idx on stock_movements (tenant_id, order_id) where order_id is not null;

